<template><view class="p"><jk-page-nav title="佣金详情"/><view v-if="detail" class="card"><view class="row"><text>佣金单号</text><b>{{detail.commissionNo || '--'}}</b></view><view class="row"><text>收益人</text><b>{{detail.applicantName || '用户不存在'}}<text v-if="detail.applicantPhone"> / {{detail.applicantPhone}}</text></b></view><view class="row"><text>收益身份</text><b>{{detail.roleName || '身份未配置'}}</b></view><view class="row"><text>来源类型</text><b>{{detail.sourceTypeText || sourceTypeText(detail.sourceType)}}</b></view><view class="row"><text>来源单据</text><b>{{detail.sourceNo || '--'}}</b></view><view class="row"><text>佣金金额</text><b>¥ {{detail.commissionAmount || 0}}</b></view><view class="row"><text>状态</text><b>{{detail.commissionStatusText || detail.statusText || commissionStatusText(detail.status)}}</b></view><view class="row"><text>创建时间</text><b>{{detail.createTime || '--'}}</b></view></view></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{getJkCommissionDetail}from'@/api/jk.js';import{jkCommissionStatusText,jkSourceTypeText}from'@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{detail:null}},onLoad(q){getJkCommissionDetail(q.id).then(r=>this.detail=r.data||r||{})},methods:{commissionStatusText(status){return jkCommissionStatusText(status)},sourceTypeText(sourceType){return jkSourceTypeText(sourceType)}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{padding:24rpx;background:#fff;border-radius:18rpx;display:flex;flex-direction:column;gap:18rpx}.row{display:flex;justify-content:space-between;gap:20rpx;color:#456}.row text{color:#78918b}.row b{color:#183a36;text-align:right}</style>
